for(const step of ENGLISH.parent.steps)extra.append(el('p',step));
if(D.priority_words?.length)extra.append(el('p','Priority review: '+D.priority_words.join(', ')));
for(const word of D.support_vocabulary||[])extra.append(el('p',`${word.word}: ${word.meaning_en} · ${word.meaning_zh}`,'word-definition-translation'));
for(const mistake of ENGLISH.mistakes)extra.append(el('p',mistake));
if(D.conversation_expressions?.length)extra.append(el('p','Useful expressions: '+D.conversation_expressions.join(' · ')));
if(D.pronunciation_tip)extra.append(el('p',D.pronunciation_tip));
for(const item of D.homework||[])extra.append(el('p','☐ '+item));if(D.conversation?.length){const d=document.createElement('div');d.className='context-block';for(const t of D.conversation)d.append(el('p',`${t.speaker}: ${t.line}`));extra.append(d)}show(0);

